// Explicit institutional/publisher/protocol APP paths; preserve original source roles.
(ReadFile as function, ArchiveBase as text, ExpectedBatch as text, TrustedPolicySHA256 as text, Previous as list) as list =>
let
    Manifest=Json.Document(ReadFile(ArchiveBase&"/manifest.json")),
    Checked=if Manifest[kind]="nhmrc_explicit_application_sources_v1" and Manifest[complete]=true and Manifest[batch]=ExpectedBatch then Manifest else error "Application source packet identity drift",
    Info=(N as text) as record => let Fs=List.Select(Checked[files],each [name]=N) in if List.Count(Fs)=1 then Fs{0} else error "Missing or duplicated application source",
    Raw=(N as text) as binary => let F=Info(N),B=Binary.Buffer(ReadFile(ArchiveBase&"/"&N)),Ps=if N="rule-authority.json" then {F} else List.Select(P[source_files],each [name]=N) in if List.Count(Ps)=1 and F[sha256]=Ps{0}[sha256] and F[bytes]=Ps{0}[bytes] and Binary.Length(B)=F[bytes] then B else error "Pinned source identity or length drift",
    Read=(N as text) as record => Json.Document(Raw(N)),
    P=if Info("rule-authority.json")[sha256]=TrustedPolicySHA256 and Text.Length(TrustedPolicySHA256)=64 then Read("rule-authority.json") else error "External application-source policy drift",
    Authorities={{"rgms-guide.pdf","92c37f512dca324ae2da039f3dea11a69d5f0901044c893d908ea11232477a3a"},{"data-dictionary.xlsx","a78740d1d3bd8686128969a7d51f5fee76528f18667648605e135b57467129d0"},{"ardc-nhmrc-terms.html","d856d8bb0858b336b2bd86aee504f2c853d82e6a0c7760e7133fe59660fd1bd8"}},
    Policy=if P[rule]="nhmrc-explicit-application-source-paths-v1" and P[namespace]="nhmrc" and P[batch]=ExpectedBatch and List.AllTrue(List.Transform(Authorities,each Info(_{0})[sha256]=_{1} and Binary.Length(Raw(_{0}))=Info(_{0})[bytes])) then P else error "Issuer representation authority drift",
    Authority=Read("authority-ror.json"),
    ROR=if List.AnyTrue(List.Transform(Authority[links],each [type]="website" and [value]="https://www.nhmrc.gov.au/")) then Authority[id] else error "NHMRC namespace authority missing",
    Upstream=Read("nhmrc-source-manifest.json"),Retention=Read("nhmrc-native-run-verification.json"),Originals=List.Select(Retention[files],each [name]="manifest.json"),
    GovernmentOriginValid=Upstream[format]="rims-funding-native-workbook-commit-v1" and Upstream[source]="nhmrc" and Upstream[complete]=true and Upstream[fidelity]="original_binary_content_exact_saved_readback" and Retention[status]="PASS_NATIVE_ORIGINAL_WORKBOOK_ARCHIVE" and Retention[run]=Upstream[run] and List.Count(Originals)=1 and Originals{0}[sha256]=Info("nhmrc-source-manifest.json")[sha256] and Originals{0}[bytes]=Info("nhmrc-source-manifest.json")[bytes],
    Number=(Code as text) as text => let N=Text.Range(Code,3) in if Text.StartsWith(Code,"APP") and Text.Length(Code)=10 and Text.Select(N,{"0".."9"})=N and not Text.StartsWith(N,"0") then N else error "Unsupported application representation",
    HTML=(N as text) as text => Text.FromBinary(Raw(N),TextEncoding.Utf8),
    Count=(S as text,T as text) as number => List.Count(Text.Split(S,T))-1,
    Meta=(S as text,N as text,V as text) as logical => Count(Text.Lower(S),"name="""&N&""" content="""&Text.Lower(V)&"""")=1,
    Government=(Q as record,N as text) as record => let Os=List.Select(Upstream[files],each [name]=Q[workbook_original_name]),Rs=List.Select(Retention[files],each [name]=Q[workbook_original_name]),F=Info(Q[workbook]),Valid=GovernmentOriginValid and List.Count(Os)=1 and List.Count(Rs)=1 and Os{0}[source_url]=Q[workbook_source_url] and Rs{0}[matches_original_CLI_capture]=true and Rs{0}[sha256]=F[sha256] and Rs{0}[bytes]=F[bytes],W=if Valid then Excel.Workbook(Raw(Q[workbook]),null,true) else error "Government source binding drift",Sheets=Table.SelectRows(W,each [Item]="GRANTS DATA" and [Kind]="Sheet"),T=if Table.RowCount(Sheets)=1 then Table.PromoteHeaders(Sheets{0}[Data],[PromoteAllScalars=true]) else error "Government primary sheet missing",Indexed=Table.AddIndexColumn(T,"__source_row",2,1,Int64.Type),Matches=Table.SelectRows(Indexed,each try Text.From(Record.Field(_,"APP ID"),"en-US")=N otherwise false) in if Table.RowCount(Matches)=1 then [target_key="nhmrc:"&N,row=Matches{0}[__source_row]] else error "Government application unresolved or ambiguous",
    AuthorityHashes=Record.FromList(List.Transform(Authorities,each _{1}),List.Transform(Authorities,each _{0})),
    Rows=List.Combine(List.Transform(Policy[cases],(Q)=>let
        Code=Q[original_identifier],N=Number(Code),Mode=Q[kind],Gov=if Mode="repository_project" then null else Government(Q,N),
        Core=[rule=Policy[rule],ruleAuthoritySHA256=TrustedPolicySHA256,originalApplicationID=Code,applicationNumber=N,authorityROR=ROR,authorityRawSHA256=Info("authority-ror.json")[sha256],representationAuthorities=AuthorityHashes,retentionBatch=ExpectedBatch],
        Provenance=if Gov=null then Core else Record.Combine({Core,[recordKind="historical_nhmrc_application",workbookRawSHA256=Info(Q[workbook])[sha256],workbookSourceURL=Q[workbook_source_url],workbookSheet="GRANTS DATA",identifierColumn="APP ID",workbookRow=Gov[row]]})
    in if Mode="protocol_government" then let
        Page=HTML(Q[cover]),Cover=Text.Combine(List.Select(Text.SplitAny(Text.BeforeDelimiter(Page&Character.FromNumber(12),Character.FromNumber(12))," #(cr)#(lf)#(tab)"),each _<>"")," "),PDF=Raw(Q[pdf]),
        NCT=Text.BeforeDelimiter(Text.AfterDelimiter(Cover,"Clinical trials registration ")," "),AnchorNumber=Text.BeforeDelimiter(Text.AfterDelimiter(Cover,"NHMRC 2021 Clinical Trials and Cohort Studies (Application ID "),")"),
        Anchors=List.Select(Previous,each [RelationshipKind]="study_award_reference" and [FromKey]="clinicaltrials.gov:"&NCT and [ToKey]="https://purl.org/au-research/grants/nhmrc/"&AnchorNumber),A=if List.Count(Anchors)=1 then Anchors{0} else error "Existing protocol binding missing or ambiguous",Proof=Json.Document(A[ReferenceType]),
        CoverValid=Count(Cover,"Clinical trials registration ")=1 and Count(Cover,"Protocol number ")=1 and Count(Cover,"Protocol version/date ")=1 and Text.Length(NCT)=11 and Text.StartsWith(NCT,"NCT") and Text.Select(Text.Range(NCT,3),{"0".."9"})=Text.Range(NCT,3) and Text.FromBinary(Binary.Range(PDF,0,5),TextEncoding.Utf8)="%PDF-" and Proof[protocolRawSHA256]=Info(Q[pdf])[sha256] and Count(Text.AfterDelimiter(Cover,"Funding source"),"National Health and Medical Research Council (NHMRC) Clinical Trials and Cohort Studies funding grant (Award ID: "&Code&")")=1 and Text.Contains(Cover,"Clinical trials registration "&Text.AfterDelimiter(A[FromKey],"clinicaltrials.gov:")) and Text.Contains(Cover,"Protocol number "&Proof[protocolIdentifier]) and Text.Contains(Cover,"Protocol version/date "&A[SourceVersion]),
        Templates=if CoverValid then List.Select(Previous,each [SourceWorkID]=A[SourceWorkID] and [ToKey]=A[ToKey] and List.Contains({"study_award_reference","publication_study_award_chain"},[RelationshipKind])) else error "Protocol source/identity/version drift",
        PMIDs=List.Distinct(List.Transform(List.Select(Previous,each [RelationshipKind]="publication_study_reference" and [ToKey]=A[FromKey] and [PublicationPMID]<>""),each [PublicationPMID])),Chains=List.Select(Templates,each [RelationshipKind]="publication_study_award_chain"),ChainIDs=List.Transform(Chains,each [PublicationPMID]),
        Coverage=List.Count(Templates)=List.Count(PMIDs)+1 and List.Count(Chains)=List.Count(PMIDs) and List.IsEmpty(List.Difference(PMIDs,ChainIDs)) and List.IsEmpty(List.Difference(ChainIDs,PMIDs)),
        Detail=Record.Combine({Provenance,[relationship="explicit_protocol_APP_to_historical_application",priorProtocolBindingEvidenceKey=A[EvidenceKey],protocolRawSHA256=Proof[protocolRawSHA256],protocolPage=1,protocolIdentifier=Proof[protocolIdentifier],protocolVersion=A[SourceVersion],studySourceRawSHA256=Proof[studySourceRawSHA256],studyRegisterSourceSHA256=Proof[studyRegisterSourceSHA256]]})
    in if Coverage then List.Transform(Templates,(T)=>let Old=Json.Document(T[ReferenceType]),D=if Record.HasFields(Old,"publicationReferenceEvidence") then Record.AddField(Detail,"publicationReferenceEvidence",Old[publicationReferenceEvidence]) else Detail,K=if Text.EndsWith(T[EvidenceKey],"|"&T[ToKey]) then Text.Start(T[EvidenceKey],Text.Length(T[EvidenceKey])-Text.Length(T[ToKey]))&Gov[target_key] else error "Protocol evidence-key drift" in Record.Combine({T,[EvidenceKey=K,ToKey=Gov[target_key],ToLabel=Code,ReferenceType=Text.FromBinary(Json.FromValue(D),TextEncoding.Utf8)]})) else error "Protocol publication-reference coverage drift"
    else let
        DOI=Text.Lower(Q[doi]),PMID=Q[pmid],Pub=HTML(Q[publication]),Refs=List.Select(Previous,each [RelationshipKind]="publication_grant_reference" and [SourceWorkID]="pubmed:"&PMID and [PublicationPMID]=PMID and Text.EndsWith([ToLabel]," | "&Code)),R=if List.Count(Refs)=1 then Refs{0} else error "Original PubMed assertion missing or ambiguous",
        Base=Record.Combine({Provenance,[originalReferenceEvidenceKey=R[EvidenceKey],originalReferenceLabel=R[ToLabel],originalReferenceSourceVersion=R[SourceVersion],publicationDOI=DOI,publicationPMID=PMID]}),
        Path=if Mode="repository_project" then let Project=HTML(Q[project]),URI="http://purl.org/au-research/grants/nhmrc/"&N,Valid=Meta(Pub,"citation_doi",DOI) and Meta(Pub,"citation_pmid",PMID) and Count(Pub,"rel=""UPMProject"" href="""&Q[project_url]&"""")=1 and Count(Project,"href="""&URI&"""")=1,Registry=Read(Q[registry]),Data=Registry[data],Matches=List.Select(Data[records],each Record.FieldOrDefault(_,"type","")="grant" and Record.FieldOrDefault(_,"purl","")="https://purl.org/au-research/grants/nhmrc/"&N and List.Contains(Record.FieldOrDefault(_,"identifiers",{}),N)) in if Valid and Registry[status]="OK" and Registry[code]="200" and Data[offset]=0 and Data[numFound]=List.Count(Data[records]) and List.Count(Matches)=1 then [Target=Matches{0}[purl],Kind="publication_award_crosswalk",Details=[relationship="explicit_repository_project_grant_application",institutionalGrantURI=URI,projectURL=Q[project_url],projectRawSHA256=Info(Q[project])[sha256],registryRawSHA256=Info(Q[registry])[sha256]]] else error "Explicit repository/project/grant path unproved"
        else if Mode="repository_government" then let URI="http://purl.org/au-research/grants/NHMRC/"&N in if Meta(Pub,"citation_doi",DOI) and Meta(Pub,"citation_pmid",PMID) and Count(Pub,"href="""&URI&"""")=1 then [Target=Gov[target_key],Kind="publication_government_award_reference",Details=[relationship="explicit_repository_grant_to_historical_application",institutionalGrantURI=URI,sourceAgencyDiscrepancy=Text.StartsWith(R[ToLabel],"Welcome Trust | ")]] else error "Explicit institutional application reference unproved"
        else if Mode="publisher_government" then let Identity=HTML(Q[identity]),Funding=try Text.BeforeDelimiter(Text.AfterDelimiter(Pub,"<section data-title=""Funding"">"),"</section>") otherwise "",Clause="National Health and Medical Research Council of Australia Investigator Grant ("&Code&", awarded to " in if Meta(Pub,"citation_doi",DOI) and Meta(Identity,"citation_doi",DOI) and Meta(Identity,"citation_pmid",PMID) and Count(Funding,Clause)=1 then [Target=Gov[target_key],Kind="publication_government_award_reference",Details=[relationship="explicit_publisher_APP_to_historical_application",identitySourceURL=Q[identity_url],identityRawSHA256=Info(Q[identity])[sha256]]] else error "Explicit publisher funding/identity path unproved"
        else error "Unsupported explicit application source path",
        Source=(if Mode="publisher_government" then "publisher:" else "repository:")&DOI,Details=Record.Combine({Base,Path[Details]})
    in {[EvidenceKey=Text.Combine({Source,Path[Kind],"doi:"&DOI,Path[Target]},"|"),RelationshipKind=Path[Kind],SourceWorkID=Source,PublicationDOI=DOI,PublicationPMID=PMID,ReferenceType=Text.FromBinary(Json.FromValue(Details),TextEncoding.Utf8),FromKey="doi:"&DOI,ToKey=Path[Target],FromLabel="NHMRC application namespace",ToLabel=Code,ORCID="",ORCIDStatus="Absent",ROR=ROR,IdentityStatus="Source-supported",SourceURL=Q[source_url],ObservedUTC=Q[observed_utc],RawSHA256=Info(Q[publication])[sha256],SourceVersion=ExpectedBatch,ReviewState="Not reviewed",AuthenticationState="Not authenticated"]})),
    Keys=List.Transform(Rows,each [EvidenceKey]),Result=if List.Count(Keys)=List.Count(List.Distinct(Keys)) then Rows else error "Duplicate application evidence identity"
in List.Buffer(Result)
